import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { TensionSynthesizer } from "../tone/TensionSynthesizer";
import * as Tone from "tone";

export class AudioDirectorSystem implements ISystem {
    readonly phase = SystemPhase.RenderSync;
    private tensionSynth: TensionSynthesizer | null = null;
    private initialized: boolean = false;
    private unsub: (() => void) | null = null;

    constructor(private broker: EventBroker) {}

    public init(): void {
        const triggerOnFirstGesture = (): void => {
            this.bootAudioEngine();
            window.removeEventListener("click", triggerOnFirstGesture);
            window.removeEventListener("keydown", triggerOnFirstGesture);
            window.removeEventListener("touchend", triggerOnFirstGesture);
            window.removeEventListener("mousedown", triggerOnFirstGesture);
        };
        window.addEventListener("click", triggerOnFirstGesture);
        window.addEventListener("keydown", triggerOnFirstGesture);
        window.addEventListener("touchend", triggerOnFirstGesture);
        window.addEventListener("mousedown", triggerOnFirstGesture);

        this.unsub = this.broker.subscribe(GameEvent.ROPE_TENSION_CHANGE, (payload) => {
            if (this.initialized && this.tensionSynth) {
                this.tensionSynth.updateDronePitch(payload.tension);
            }
        });
    }

    public update(_dt: number): void {
        // Audio logic updates
    }

    private bootAudioEngine(): void {
        if (this.initialized) return;
        Tone.start().then(() => {
            this.initialized = true;
            this.tensionSynth = new TensionSynthesizer();
            this.tensionSynth.initialize();
            this.broker.publish(GameEvent.USER_GESTURE_REGISTERED, undefined);
        });
    }

    public dispose(): void {
        if (this.unsub) this.unsub();
        if (this.tensionSynth) this.tensionSynth.dispose();
    }
}

src/audio/tone/TensionSynthesizer.ts:
import * as Tone from "tone";

export class TensionSynthesizer {
  private fmOsc: Tone.FMOscillator | null = null;
  private lowpassFilter: Tone.Filter | null = null;
  private gainNode: Tone.Gain | null = null;
  private lfo: Tone.LFO | null = null;

  public initialize(): void {
    this.lowpassFilter = new Tone.Filter({
      frequency: 200,
      type: "lowpass",
      Q: 4.0
    }).toDestination();

    this.fmOsc = new Tone.FMOscillator({
      frequency: 55,
      type: "sawtooth",
      modulationType: "sine",
      harmonicity: 1.5,
      modulationIndex: 5
    });

    this.gainNode = new Tone.Gain(0.15);

    this.lfo = new Tone.LFO({
      frequency: 0.2,
      min: 150,
      max: 280
    });

    this.fmOsc.connect(this.gainNode);
    this.gainNode.connect(this.lowpassFilter);
    this.lfo.connect(this.lowpassFilter.frequency);

    this.lfo.start();
    this.fmOsc.start();
  }

  public updateDronePitch(tensionVal: number): void {
    if (!this.fmOsc || !this.gainNode || !this.lowpassFilter) return;

    const now = Tone.now();
    const clampedTension = Math.max(0, Math.min(1, tensionVal));

    const targetBaseFreq = 55 + clampedTension * 55;
    const targetModulationIndex = 5 + clampedTension * 25;
    const targetGain = 0.15 + clampedTension * 0.12;

    this.fmOsc.frequency.setTargetAtTime(targetBaseFreq, now, 0.1);
    this.fmOsc.modulationIndex.setTargetAtTime(targetModulationIndex, now, 0.1);
    this.gainNode.gain.setTargetAtTime(targetGain, now, 0.08);
  }

  public dispose(): void {
    if (this.fmOsc) {
      this.fmOsc.stop();
      this.fmOsc.dispose();
    }
    if (this.lfo) {
      this.lfo.stop();
      this.lfo.dispose();
    }
    if (this.lowpassFilter) {
      this.lowpassFilter.dispose();
    }
    if (this.gainNode) {
      this.gainNode.dispose();
    }
  }
}

src/babylon/cameras/CameraSystem.ts:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { IVisualRegistry } from "../../contracts/IVisualRegistry";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { TransformComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import * as BABYLON from "@babylonjs/core";

export class CameraSystem implements ISystem {
    readonly phase = SystemPhase.RenderSync;
    private cameraNode: BABYLON.FreeCamera | null = null;
    private shakeIntensity = 0.0; 
    private shakeTimeRemaining = 0.0; 
    private unsub: (() => void) | null = null;

    private currentTarget = new BABYLON.Vector3(0, 10, -25);
    private springPosition = new BABYLON.Vector3(0, 10, -25);
    private springVelocity = new BABYLON.Vector3(0, 0, 0);

    private scratchLookAt = new BABYLON.Vector3();

    constructor(
        private refs: EntityRefs, 
        private transforms: ComponentStore<TransformComponent>, 
        private visualRegistry: IVisualRegistry,
        private broker: EventBroker
    ) {}

    public init(): void {
        const scene = this.visualRegistry.getScene();
        if (scene && scene.activeCamera) {
            this.cameraNode = scene.activeCamera as BABYLON.FreeCamera;
            this.springPosition.copyFrom(this.cameraNode.position);
        }

        this.unsub = this.broker.subscribe(GameEvent.CAMERA_SHAKE_TRIGGERED, (payload) => {
            this.shakeIntensity = Math.max(this.shakeIntensity, payload.amplitude);
            this.shakeTimeRemaining = Math.max(this.shakeTimeRemaining, payload.duration);
        });
    }

    public update(dt: number): void {
        if (!this.cameraNode) {
            const scene = this.visualRegistry.getScene();
            if (scene && scene.activeCamera) {
                this.cameraNode = scene.activeCamera as BABYLON.FreeCamera;
                this.springPosition.copyFrom(this.cameraNode.position);
            }
            return;
        }

        const p = this.transforms.get(this.refs.player); 
        const w = this.transforms.get(this.refs.warden);

        if (p) {
            let fx = p.x, fy = p.y;
            if (w) { 
                fx = p.x * 0.7 + w.x * 0.3; 
                fy = p.y * 0.7 + w.y * 0.3; 
            }
            this.currentTarget.set(fx, fy + 1.5, -24.0);
        }

        const stiffness = 8.0, damping = 3.5;
        const forceX = (this.currentTarget.x - this.springPosition.x) * stiffness - this.springVelocity.x * damping;
        const forceY = (this.currentTarget.y - this.springPosition.y) * stiffness - this.springVelocity.y * damping;

        this.springVelocity.x += forceX * dt; 
        this.springVelocity.y += forceY * dt;
        this.springPosition.x += this.springVelocity.x * dt; 
        this.springPosition.y += this.springVelocity.y * dt;

        this.cameraNode.position.copyFrom(this.springPosition);

        if (this.shakeTimeRemaining > 0) {
            this.shakeTimeRemaining -= dt;
            const ci = this.shakeIntensity * (this.shakeTimeRemaining / 0.5);
            if (ci > 0) { 
                this.cameraNode.position.x += (Math.random() - 0.5) * ci * 2.5; 
                this.cameraNode.position.y += (Math.random() - 0.5) * ci * 2.5; 
            }
        } else {
            this.shakeIntensity = 0;
        }

        this.scratchLookAt.set(this.currentTarget.x, this.currentTarget.y, 0);
        this.cameraNode.setTarget(this.scratchLookAt);
    }

    public dispose(): void { 
        if (this.unsub) this.unsub(); 
    }
}

