    { minX: -15, maxX: -14, minY: 0, maxY: 30, minZ: -2, maxZ: 2 },
    { minX: 14, maxX: 15, minY: 0, maxY: 30, minZ: -2, maxZ: 2 },
    { minX: -15, maxX: 15, minY: 0, maxY: 1, minZ: -2, maxZ: 2 },
